#include "PluginProcessor.h"
#include "PluginEditor.h"
using namespace juce;
static AudioBuffer<float> speech(const char* f, double& sr) { AudioFormatManager m; m.registerBasicFormats(); std::unique_ptr<AudioFormatReader> r(m.createReaderFor(File(f))); AudioBuffer<float> b(2, (int)r->lengthInSamples); r->read(&b, 0, b.getNumSamples(), 0, true, true); sr = r->sampleRate; return b; }
static void render(SpeakitProcessor& p, AudioBuffer<float> in, double sr, int bs, AudioBuffer<float>& out) { p.prepareToPlay(sr, bs); Thread::sleep(250); AudioBuffer<float> w(2, 2048 * 2); MidiBuffer mb; for (int i = 0; i < 12; ++i) { w.clear(); AudioBuffer<float> c(w.getArrayOfWritePointers(), 2, bs); p.processBlock(c, mb); Thread::sleep(5); } out.setSize(2, in.getNumSamples()); for (int s = 0; s < in.getNumSamples(); s += bs) { int n = jmin(bs, in.getNumSamples() - s); AudioBuffer<float> c(2, n); c.copyFrom(0, 0, in, 0, s, n); c.copyFrom(1, 0, in, 1, s, n); p.processBlock(c, mb); out.copyFrom(0, s, c, 0, 0, n); out.copyFrom(1, s, c, 1, 0, n); } }
static void save(const AudioBuffer<float>& b, double sr, const String& f) { File o(f); o.deleteFile(); WavAudioFormat w; std::unique_ptr<AudioFormatWriter> wr(w.createWriterFor(new FileOutputStream(o), sr, 2, 16, {}, 0)); wr->writeFromAudioSampleBuffer(b, 0, b.getNumSamples()); }
int main(int c, char** v) { ScopedJuceInitialiser_GUI gui; String outDir = v[2];
  if (c > 3) { SpeakitProcessor p; auto* ed = dynamic_cast<SpeakitEditor*>(p.createEditor()); ed->setSize(880, 880); ed->setVisible(true); ed->addToDesktop(ComponentPeer::windowHasTitleBar); MessageManager::getInstance()->runDispatchLoopUntil(800); ed->testMenu(String(v[3]).getIntValue()); MessageManager::getInstance()->runDispatchLoopUntil(4000); PopupMenu::dismissAllActiveMenus(); MessageManager::getInstance()->runDispatchLoopUntil(200); delete ed; return 0; } double sr; auto in = speech(v[1], sr); int fails = 0;
  { SpeakitProcessor p; auto set = [&](const char* id, float x) { auto* q = p.apvts.getParameter(id); q->setValueNotifyingHost(q->convertTo0to1(x)); };
    for (auto r : { 44100.0, 48000.0, 96000.0 }) { p.prepareToPlay(r, 512); printf("latency @%g: %d samples (%.1f ms)\n", r, p.getLatencySamples(), 1000.0 * p.getLatencySamples() / r); }
    // impulse aligned at wet=0 and null test against input
    p.setCurrentProgram(0); set("wet", 0); set("limiter", 0); for (auto& b : p.bay) for (auto& s : b) s.on = false; AudioBuffer<float> o; render(p, in, sr, 512, o); int L = p.getLatencySamples(); double e = 0, s2 = 0; int skip = 48000; for (int i = skip; i < in.getNumSamples() - L; ++i) { double d = o.getSample(0, i + L) - in.getSample(0, i); e += d * d; s2 += in.getSample(0, i) * in.getSample(0, i); } double nl = 10 * log10(e / s2 + 1e-20); printf("dry null: %.1f dB\n", nl); if (nl > -60) ++fails; set("wet", 1); set("limiter", 1); }
  for (int i = 0;; ++i) { SpeakitProcessor p; if (i >= p.getNumPrograms()) break; p.setCurrentProgram(i); p.service(); p.waitForBay(); AudioBuffer<float> o; auto t0 = Time::getMillisecondCounterHiRes(); render(p, in, sr, 256, o); auto t1 = Time::getMillisecondCounterHiRes() - 400; float pk = o.getMagnitude(0, o.getNumSamples()); double rms = o.getRMSLevel(0, 0, o.getNumSamples()); bool bad = false; for (int s = 0; s < o.getNumSamples(); ++s) if (!std::isfinite(o.getSample(0, s))) { bad = true; break; } double rt = (t1 - t0) / (1000.0 * o.getNumSamples() / sr); printf("%2d %-28s pk %6.1f rms %6.1f cpu %.0f%% %s\n", i, p.getProgramName(i).toRawUTF8(), Decibels::gainToDecibels(pk), Decibels::gainToDecibels(rms), rt * 100, bad ? "NaN!" : ""); if (bad || pk < 1e-3f) ++fails; save(o, sr, outDir + "/preset_" + String(i).paddedLeft('0', 2) + ".wav"); }
  { SpeakitProcessor p; p.setCurrentProgram(0); MemoryBlock m; p.getStateInformation(m); SpeakitProcessor q; q.setStateInformation(m.getData(), (int)m.getSize()); printf("state roundtrip preset %d\n", q.getCurrentProgram());
    p.setPlayConfigDetails(2, 2, 48000, 512); p.prepareToPlay(48000, 512); auto* ed = dynamic_cast<SpeakitEditor*>(p.createEditor()); ed->setSize(966, 966); for (int pg = 0; pg < 4; ++pg) { ed->setPage(pg); auto im = ed->createComponentSnapshot(ed->getLocalBounds(), true, 1.5f); File f(outDir + "/ui_" + String(pg) + ".png"); f.deleteFile(); FileOutputStream st(f); PNGImageFormat().writeImageToStream(im, st); } delete ed; }
  printf("fails %d\n", fails); return fails; }
